      var offsetY = 0.3 // \u9AD8\u5EA6  -- \u8D8A\u5927\u9AD8\u5EA6\u8D8A\u9AD8

      var speed = 0.2 // x\u8F74 \u79FB\u52A8\u8DDD\u79BB

