`,paraId:18,tocIndex:5},{value:`/**
* 6.
* @param {function} fn \u6267\u884C\u65B9\u6CD5
* @param {number} wait \u7B49\u5F85\u65F6\u95F4
* @param {\u914D\u7F6E} options leading\uFF1A\u662F\u5426\u5141\u8BB8\u7ACB\u5373\u6267\u884C trailing\uFF1A\u662F\u5426\u5141\u8BB8\u6700\u540E\u4E00\u6B21\u6267\u884C
* @returns
*/
function throttle(fn, wait, options) {
  options = options || {}
  var result, context, args, timeout
  var prev = 0
  var later = function(){
    prev = options.leading === false ? 0 : +new Date()
    timeout = null
    result =fn.apply(context, args)
  }
  var t = function(){
    var now = +new Date()
    prev = !prev && options.leading === false ? now : prev
    var r = wait - (now - prev)
    context = this
    args = arguments
    if(r > wait || r <= 0){
      if(timeout){
        clearTimeout(timeout)
        timeout = null
      }
      prev = now
      result = fn.apply(context, args)
    }else if(!timeout && options.trailing !== false){
      timeout = setTimeout(later, r)
    }
    return result
  }
  t.cancel = function(){
    clearTimeout(timeout)
    timeout = null
    prev = 0
  }
  return t
}
