interface FooProp {
  name: string;
  X: number;
  Y: number;
}
declare function AnotherComponent(prop: { name: string });
// \u51FD\u6570\u7EC4\u4EF6\u53EF\u4EE5\u662F\u666E\u901A\u7684\u51FD\u6570
function ComponentFoo(prop: FooProp) {
  return <AnotherComponent name={prop.name} />;
}
// \u4E5F\u53EF\u4EE5\u662F\u7BAD\u5934\u51FD\u6570\u8868\u8FBE\u5F0F
const Button = (prop: { value: string }, context: { color: string }) => (
  <button />
    );

