// Project: [~\u5DE5\u7A0B\u540D~]
// Definitions by: [~\u6C5D\u540D~] <[~\u4F60\u7684\u4E3B\u9875\u94FE\u63A5~]>
/*~ \u5982\u679C\u8FD9\u4E2A\u5E93\u53EF\u4EE5\u76F4\u63A5\u8FDB\u884C\u8C03\u7528\uFF08\u7C7B\u4F3C\u6A21\u5757\u51FD\u6570\uFF09,
 *~ \u5219\u5728\u6B64\u58F0\u660E\u8C03\u7528\u7B7E\u540D\uFF0C
 *~ \u5426\u5219\uFF0C\u79FB\u9664\u8FD9\u4E00\u6BB5\u3002
 */
declare function myLib(a: string): string;
declare function myLib(a: number): number;
/*~ \u5982\u679C\u5E0C\u671B\u8FD9\u4E2A\u5E93\u7684\u540D\u5B57\u53EF\u4EE5\u4F5C\u4E3A\u6709\u6548\u7684\u7C7B\u578B\u540D,
 *~ \u5219\u5728\u6B64\u5904\u7F16\u5199\uFF0C
 *~ \u5426\u5219\u53EF\u79FB\u9664\u672C\u6BB5\u3002
 *~
 *~ \u5982\u4E0B\u793A\u4F8B\u5C06\u5141\u8BB8\u6211\u4EEC\u5B9A\u4E49\u53D8\u91CF 'var x: myLib';
 */
interface myLib {
  name: string;
  length: number;
  extras?: string[];
}
/*~ \u5982\u679C\u8FD9\u4E2A\u5E93\u66B4\u9732\u7684\u5168\u5C40\u53D8\u91CF\u4E0A\u6709\u5176\u5B83\u5C5E\u6027,
 *~ \u5219\u5728\u8FD9\u91CC\u8FDB\u884C\u58F0\u660E.
 *~ \u5F53\u7136\u4E5F\u8981\u58F0\u660E\u76F8\u5E94\u7684\u7C7B\u578B(\u63A5\u53E3\u6216\u7C7B\u578B\u522B\u540D)\u3002
 */
declare namespace myLib {
  //~ \u53D8\u91CF\uFF0C'myLib.timeout = 50;'
  let timeout: number;
  //~ \u5E38\u91CF
  const version: string;
  //~ \u547D\u540D\u7A7A\u95F4\u4E2D\u5D4C\u5957\u7C7B\uFF0C\u53EF\u4EE5\u901A\u8FC7new\u6765\u521B\u5EFA\uFF1A'let c = new myLib.Cat(42)'
  //~ \u6216\u8005\u5F15\u7528\u5176\u6784\u9020\u51FD\u6570\uFF0C\u5982\uFF1A'function f(c: myLib.Cat) { ... }
  class Cat {
    constructor(n: number);
    //~ \u7C7B\u7684\u53EA\u8BFB\u5B9E\u4F8B\u5C5E\u6027
    readonly age: number;
    //~ \u7C7B\u7684\u5B9E\u4F8B\u65B9\u6CD5
    purr(): void;
  }
  //~ \u4F7F\u7528interface\u58F0\u660E\u5305\u542B\u7684\u7C7B\u578B\uFF0C\u4F7F\u5F97\u5982\u4E0B\u64CD\u4F5C\u662Fok\u7684\uFF1A
  //~   'var s: myLib.CatSettings = { weight: 5, name: "Maru" };'
  interface CatSettings {
    weight: number;
    name: string;
    tailLength?: number;
  }
  //~ \u4F7F\u7528\u7C7B\u578B\u522B\u540D\u6765\u58F0\u660E\u7C7B\u578B\uFF1A
  type VetID = string | number;
  //~ \u58F0\u660E\u65B9\u6CD5\uFF0C\u672C\u793A\u4F8B\u53EF\u4EE5\u901A\u8FC7\u5982\u4E0B\u65B9\u5F0F\u8C03\u7528\uFF1A
  //~ 'myLib.checkCat(c)' or 'myLib.checkCat(c, v);'
  function checkCat(c: Cat, s?: VetID);
}
