`,paraId:8,tocIndex:3},{value:"\u5B9A\u4E49\uFF1A\u4E3A\u4E0D\u540C\u6570\u636E\u7C7B\u578B\u7684\u5B9E\u4F53\uFF08\u5B50\u7C7B\u5B9E\u4F53\uFF09\u63D0\u4F9B\u7EDF\u4E00\u7684\u63A5\u53E3\uFF08\u7236\u7C7B\u7C7B\u578B\u7684\u5F15\u7528\uFF09",paraId:9,tocIndex:4},{value:"\u7236\u7C7B\u5B9A\u4E49\u65B9\u6CD5\uFF0C\u4F46\u662F\u4E0D\u5B9E\u73B0\uFF0C\u8BA9\u5176\u5B50\u7C7B\u53BB\u5B9E\u73B0\uFF0C\u6BCF\u4E2A\u5B50\u7C7B\u90FD\u6709\u4E0D\u540C\u7684\u8868\u73B0 \u591A\u6001\u5C5E\u4E8E\u7EE7\u627F",paraId:10,tocIndex:4},{value:`// \u521B\u5EFA \u7236\u7C7B
class Plant {
  name: string;
  constructor(name: string) {
    this.name = name;
  }
  say(): void {
    console.log(this.name);
  }
}

// \u521B\u5EFA \u5B50\u7C7B\u4E00
class Tree extends Plant {
  age: number;
  constructor(age: number, name: string) {
    super(name);
    this.age = age;
  }
  say(): void {
    console.log(this.name + this.age);
  }
}
// \u521B\u5EFA \u5B50\u7C7B\u4E8C
class Grass extends Plant {
  grade: string;
  constructor(grade: string, name: string) {
    super(name);
    this.grade = grade;
  }
  say(): void {
    console.log(this.name + this.grade);
  }
}

// \u5E38\u89C4\uFF1A\u7236\u7C7B\u7C7B\u578B\u5F15\u7528\u6307\u5411\u7236\u7C7B\u5B9E\u4F8B
let plant: Plant = new Plant("\u4EBA");

// \u591A\u6001\u4E00\uFF1A\u7236\u7C7B\u7C7B\u578B\u5F15\u7528\u6307\u5411\u5B50\u7C7B\u5B9E\u4F8B\u5BF9\u8C61
let tree: Plant = new Tree(18, "\u5C0F\u660E");

// \u591A\u6001\u4E8C\uFF1A\u7236\u7C7B\u7C7B\u578B\u5F15\u7528\u6307\u5411\u5B50\u7C7B\u5B9E\u4F8B\u5BF9\u8C61
let grass: Plant = new Grass("\u9AD8\u4E8C", "\u5F20\u8001\u5E08");

// \u591A\u6001\u7684\u4F5C\u7528\uFF1A\u4E0D\u540C\u7C7B\u578B\u7684\u5BF9\u8C61\uFF08\u5FC5\u987B\u662F\u7236\u5B50\u5173\u7CFB\uFF09\u9488\u5BF9\u76F8\u540C\u7684\u65B9\u6CD5\uFF0C\u4EA7\u751F\u4E86\u4E0D\u540C\u7684\u884C\u4E3A
function sayWhat(who: Plant) {
  who.say(); // \u6267\u884C\u5171\u6709\u7684\u65B9\u6CD5
}

sayWhat(plant); // \u4F20\u5165 \u7236\u7C7B\u5B9E\u4F8B\u5BF9\u8C61
sayWhat(tree); // \u4F20\u5165 \u5B50\u7C7B\u5B9E\u4F8B\u5BF9\u8C61
sayWhat(grass); // \u4F20\u5165 \u5B50\u7C7B\u5B9E\u4F8B\u5BF9\u8C61


//\u7C7B\u7684\u6210\u5458\u65B9\u6CD5\u53EF\u4EE5\u76F4\u63A5\u8FD4\u56DE this\uFF0C\u8FD9\u6837\u53EF\u4EE5\u65B9\u4FBF\u7684\u5B9E\u73B0\u94FE\u5F0F\u8C03\u7528
class WorkFlow {
  step1() {
    return this
  }
  step2() {
    return this
  }
}

new WorkFlow().step1().step2()

// \u53EF\u4EE5\u5B9E\u73B0\u591A\u6001
class MyFlow extends WorkFlow {
  next() {
    return this
  }
}

new MyFlow().next().step1().next().step2()
